-- Project Catalogue Filters V2 — Phase 1: governed taxonomy, source-backed metadata, role families and readiness.
-- Source evidence: Mettelo_Project_Library_AI_Ready_Domain_Sheets_v15.xlsx (import batch fingerprint 61eda9609895c517b1fb54df2c9fb1b079dcd9c76bccaf7293ca82df0dd4006c).
-- This migration is intentionally idempotent. It does not change application, membership, Lab, Proof or Capability Path lifecycle semantics.

alter table public.projects add column if not exists catalogue_working_model_source text not null default 'unspecified';
do $$ begin
  alter table public.projects add constraint projects_catalogue_working_model_source_check check (catalogue_working_model_source in ('unspecified','explicit','platform_remote_default','not_applicable'));
exception when duplicate_object then null; end $$;

update public.projects set catalogue_working_model_source='explicit' where location_type is not null and catalogue_working_model_source='unspecified';
-- Product policy for the current catalogue: existing Mettelo Open Projects are digitally delivered/remote unless an explicit working model already exists.
-- This is a one-time backfill, not a database default: future authoring must explicitly classify working model before publication.
update public.projects set location_type='remote', catalogue_working_model_source='platform_remote_default'
where project_type='open' and visibility in ('public','members') and location_type is null;

on conflict (slug) do update set title=excluded.title, active=true, sort_order=excluded.sort_order, updated_at=now();

create table if not exists public.project_role_families (
  project_id uuid not null references public.projects(id) on delete cascade,
  role_catalogue_id uuid not null references public.project_role_catalogue(id) on delete restrict,
  source text not null default 'catalogue_v2',
  created_at timestamptz not null default now(),
  primary key(project_id,role_catalogue_id)
);
create index if not exists project_role_families_role_idx on public.project_role_families(role_catalogue_id,project_id);
alter table public.project_role_families enable row level security;
drop policy if exists "visible project role families are readable" on public.project_role_families;
create policy "visible project role families are readable" on public.project_role_families for select using (
  exists(select 1 from public.projects p where p.id=project_id and p.visibility='public')
  or exists(select 1 from public.project_members pm where pm.project_id=project_id and pm.user_id=(select auth.uid()))
  or is_admin()
);

on conflict (slug) do update set name=excluded.name, capability_type=excluded.capability_type, sort_order=excluded.sort_order, is_active=true, updated_at=now();

create table if not exists public.capability_aliases (
  alias text primary key,
  capability_id uuid not null references public.capabilities(id) on delete cascade,
  created_at timestamptz not null default now(),
  constraint capability_aliases_normalized_check check (alias=lower(btrim(alias)) and length(alias)>0)
);
create index if not exists capability_aliases_capability_idx on public.capability_aliases(capability_id);
alter table public.capability_aliases enable row level security;
drop policy if exists "active capability aliases are readable" on public.capability_aliases;
create policy "active capability aliases are readable" on public.capability_aliases for select using (
  exists(select 1 from public.capabilities c where c.id=capability_id and c.is_active) or is_admin()
);
