create temp table tmp_project_catalogue_v2_source (
  source_key text primary key, domain_slug text not null, tool_slugs text[] not null, method_slugs text[] not null, role_slugs text[] not null, capability_slugs text[] not null
) on commit drop;


create temp table tmp_project_catalogue_v2_projects on commit drop as
select distinct on (o.project_id) o.project_id,s.*
from public.capability_path_import_project_origins o
join tmp_project_catalogue_v2_source s on s.source_key=o.source_project_key
order by o.project_id,o.created_at desc;

select p.project_id,r.id,'governed_workbook_v15'
from tmp_project_catalogue_v2_projects p
cross join lateral unnest(p.role_slugs) as x(slug)
join public.project_role_catalogue r on r.slug=x.slug and r.active
on conflict (project_id,role_catalogue_id) do nothing;

select p.project_id,c.id,'core',true
from tmp_project_catalogue_v2_projects p
cross join lateral unnest(p.capability_slugs) as x(slug)
join public.capabilities c on c.slug=x.slug and c.is_active
on conflict (project_id,capability_id) do update set importance='core', evidence_expected=true;

select p.project_id,d.id,not exists(select 1 from public.project_domains pd where pd.project_id=p.project_id and pd.is_primary)
from tmp_project_catalogue_v2_projects p
join public.domains d on d.slug=p.domain_slug and d.is_active
on conflict (project_id,domain_id) do nothing;

select p.project_id,t.id from tmp_project_catalogue_v2_projects p
cross join lateral unnest(p.tool_slugs) as x(slug)
join public.tools t on t.slug=x.slug and t.is_active
on conflict (project_id,tool_id) do nothing;

select p.project_id,m.id from tmp_project_catalogue_v2_projects p
cross join lateral unnest(p.method_slugs) as x(slug)
join public.methods m on m.slug=x.slug and m.is_active
on conflict (project_id,method_id) do nothing;

