create or replace view public.project_catalogue_readiness with (security_invoker=true) as
select
  p.id as project_id, p.slug, p.title, p.visibility, p.status, p.project_type, p.location_type, p.catalogue_working_model_source, p.duration_weeks, p.weekly_commitment,
  coalesce(r.role_family_count,0) as role_family_count, coalesce(c.capability_count,0) as capability_count, coalesce(d.domain_count,0) as domain_count,
  coalesce(t.tool_count,0) as tool_count, coalesce(m.method_count,0) as method_count,
  (p.project_type in ('open','partner')) as project_type_ready,
  (coalesce(r.role_family_count,0)>=1) as roles_ready,
  (coalesce(d.domain_count,0)>=1) as domain_ready,
  (coalesce(c.capability_count,0)>=3) as capabilities_ready,
  coalesce(p.location_type in ('remote','hybrid','onsite'),false) as working_model_ready,
  (p.duration_weeks is not null and p.duration_weeks>0) as duration_ready,
  (nullif(btrim(p.weekly_commitment),'') is not null) as commitment_ready,
  (p.status in ('draft','pilot','recruiting','open','forming','active','review','completed','cancelled','archived')) as stage_ready,
  array_remove(array[
    case when not (p.project_type in ('open','partner')) then 'project_type' end,
    case when coalesce(r.role_family_count,0)<1 then 'roles' end,
    case when coalesce(d.domain_count,0)<1 then 'domain' end,
    case when coalesce(c.capability_count,0)<3 then 'capabilities' end,
    case when not coalesce(p.location_type in ('remote','hybrid','onsite'),false) then 'working_model' end,
    case when not (p.duration_weeks is not null and p.duration_weeks>0) then 'duration' end,
    case when nullif(btrim(p.weekly_commitment),'') is null then 'commitment' end
  ],null) as missing_requirements,
  ((p.project_type in ('open','partner')) and coalesce(r.role_family_count,0)>=1 and coalesce(d.domain_count,0)>=1 and coalesce(c.capability_count,0)>=3
    and coalesce(p.location_type in ('remote','hybrid','onsite'),false) and p.duration_weeks is not null and p.duration_weeks>0 and nullif(btrim(p.weekly_commitment),'') is not null) as catalogue_ready
from public.projects p
left join lateral (select count(*)::int role_family_count from public.project_role_families x where x.project_id=p.id) r on true
left join lateral (select count(*)::int capability_count from public.project_capabilities x where x.project_id=p.id) c on true
left join lateral (select count(*)::int domain_count from public.project_domains x where x.project_id=p.id) d on true
left join lateral (select count(*)::int tool_count from public.project_tools x where x.project_id=p.id) t on true
left join lateral (select count(*)::int method_count from public.project_methods x where x.project_id=p.id) m on true;

grant select on public.project_catalogue_readiness to anon,authenticated;

comment on view public.project_catalogue_readiness is 'Project Catalogue Filters V2 readiness. Tools/methods are informative; role, domain, 3+ capabilities, working model, duration and commitment are required for discoverable catalogue readiness.';
